  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 DNA Structure and Replication$j$, $j${"readings": [{"title": "Psalm 139 (King James Version)", "url": "/portal/bible/Psalms/139"}], "body": "DNA (deoxyribonucleic acid) carries the instructions for building and running a living thing. Psalm 139:16 says, Thine eyes did see my substance, yet being unperfect; and in thy book all my members were written, which in continuance were fashioned, when as yet there was none of them.\n\nStructure: DNA is a double helix, like a twisted ladder. It is a polymer of nucleotides. Each nucleotide has a sugar (deoxyribose), a phosphate group and a nitrogen base. The sugar and phosphate form the sides of the ladder. The bases form the rungs.\n\nThe four bases are adenine (A), thymine (T), guanine (G) and cytosine (C). Base pairing rules: A pairs with T, and C pairs with G. Hydrogen bonds hold the pairs together. Because of these rules, if one strand reads ATGC, the other strand reads TACG. In any DNA, the amount of A equals T and the amount of C equals G.\n\nDiscovery: Rosalind Franklin's X ray images and Maurice Wilkins's work, together with the models of James Watson and Francis Crick, revealed the double helix in 1953. Chargaff discovered that A equals T and C equals G.\n\nReplication: DNA copies itself before a cell divides (S phase). The enzyme helicase unwinds and unzips the two strands. DNA polymerase adds matching nucleotides to each strand. The result is two identical DNA molecules, each with one old strand and one new strand. This is called semiconservative replication. Proofreading by DNA polymerase keeps errors very rare.\n\nA gene is a section of DNA that codes for a protein. DNA is wrapped around proteins to form chromosomes in the nucleus.\n\nYour task: (1) Write the complementary strand for ATTGCA. (2) If a sample has 30 percent adenine, how much is cytosine? (3) Explain why replication is called semiconservative.\n\nFlorida standards: SC.912.L.16.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.16.3", "script": "Welcome to Unit 4. This is Dr. Jenkins. Listen, Psalm one thirty nine and sixteen says, Thine eyes did see my substance, yet being unperfect; and in thy book all my members were written, which in continuance were fashioned, when as yet there was none of them. Today we study the book of instructions written in every cell, DNA.\n\nNow watch this. DNA is a double helix, like a twisted ladder. It is a polymer of nucleotides. Each nucleotide has a sugar called deoxyribose, a phosphate group and a nitrogen base. The sugar and phosphate form the sides of the ladder, and the bases form the rungs.\n\nLook at the four bases. Adenine, thymine, guanine and cytosine. A pairs with T, and C pairs with G. Hydrogen bonds hold the pairs together. So if one strand reads A T G C, the other strand reads T A C G. In any DNA, the amount of A equals the amount of T, and the amount of C equals the amount of G. The double helix was revealed in nineteen fifty three through the X ray images of Rosalind Franklin, the work of Maurice Wilkins, and the models of Watson and Crick, building on Chargaff's rules.\n\nHere is replication. Before a cell divides, in S phase, DNA copies itself. The enzyme helicase unwinds and unzips the two strands. DNA polymerase adds matching nucleotides to each strand. The result is two identical molecules, each with one old strand and one new strand. We call that semiconservative replication. DNA polymerase also proofreads, so errors are rare.\n\nA gene is a section of DNA that codes for a protein, and DNA wraps around proteins to form chromosomes in the nucleus.\n\nYour task today. Write the complementary strand for A T T G C A. If a sample has thirty percent adenine, how much is cytosine? And explain why replication is called semiconservative. Take the four question check when you finish.\n\nThe Author of life wrote with order and care. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 DNA Structure and Replication$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 From Gene to Protein and Mutations$j$, $j${"readings": [{"title": "Proverbs 3 (King James Version)", "url": "/portal/bible/Proverbs/3"}], "body": "A gene is a set of instructions for making a protein, and proteins carry out most of the work of the cell. Proverbs 3:13 says, Happy is the man that findeth wisdom, and the man that getteth understanding.\n\nRNA (ribonucleic acid) differs from DNA: it has the sugar ribose, is usually single stranded, and has uracil (U) instead of thymine. In RNA, A pairs with U.\nThree types: mRNA (messenger, carries the copy of a gene), tRNA (transfer, brings amino acids) and rRNA (ribosomal, part of the ribosome).\n\nThe central idea: DNA to RNA to protein.\n\nTranscription (in the nucleus): RNA polymerase reads one DNA strand and builds an mRNA copy. DNA TAC GGA becomes mRNA AUG CCU. The mRNA leaves the nucleus through a pore.\n\nTranslation (at the ribosome): The ribosome reads the mRNA three bases at a time. Each three base group is a codon, and each codon codes for one amino acid or a signal. AUG is the start codon and codes for methionine. UAA, UAG and UGA are stop codons. A tRNA has an anticodon that matches the codon and carries the amino acid. Amino acids are joined into a chain that folds into a protein.\n\nExample: mRNA AUG CCU UUU codes for methionine, proline and phenylalanine.\n\nThe genetic code is nearly universal, meaning almost all living things use the same code.\n\nMutations are changes in DNA. A substitution changes one base. An insertion or deletion adds or removes a base and shifts the reading frame (a frameshift), which can change every amino acid after it. Some mutations are harmless, some cause disease (sickle cell disease comes from one base change), and a few are helpful. Mutations in sex cells can be passed on. Causes include copying errors, radiation and some chemicals.\n\nYour task: (1) Transcribe the DNA strand TACCGT into mRNA. (2) Explain why a frameshift is usually more serious than a substitution. (3) Tell the roles of mRNA and tRNA.\n\nFlorida standards: SC.912.L.16.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.16.3", "script": "Welcome back. Dr. Jenkins here. Listen, Proverbs three and thirteen says, Happy is the man that findeth wisdom, and the man that getteth understanding. Today we understand how a gene becomes a protein.\n\nFirst, RNA. It differs from DNA. It has the sugar ribose, it is usually single stranded, and it has uracil instead of thymine, so in RNA, A pairs with U. There are three types. Messenger RNA carries the copy of a gene. Transfer RNA brings amino acids. Ribosomal RNA is part of the ribosome. The central idea is DNA to RNA to protein.\n\nNow watch this. Transcription happens in the nucleus. RNA polymerase reads one DNA strand and builds an mRNA copy. DNA T A C G G A becomes mRNA A U G C C U. The mRNA leaves the nucleus through a pore.\n\nTranslation happens at the ribosome. The ribosome reads the mRNA three bases at a time. Each group is a codon, and each codon codes for one amino acid or a signal. A U G is the start codon and codes for methionine. U A A, U A G and U G A are stop codons. A tRNA has an anticodon that matches the codon and carries the amino acid. The amino acids join in a chain that folds into a protein. For example, A U G, C C U, U U U codes for methionine, proline and phenylalanine. The genetic code is nearly universal, so almost every living thing uses the same code.\n\nLook at mutations. A mutation is a change in DNA. A substitution changes one base. An insertion or deletion shifts the reading frame, called a frameshift, and can change every amino acid after it. Some mutations are harmless, some cause disease, like sickle cell disease from one base change, and a few are helpful. Mutations in sex cells can be passed on.\n\nYour task today. Transcribe T A C C G T into mRNA. Explain why a frameshift is usually more serious than a substitution. And tell the roles of mRNA and tRNA. Take the four question check when you finish.\n\nUnderstanding is a gift worth seeking. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 From Gene to Protein and Mutations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Meiosis and Genetic Variation$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "Mitosis makes identical body cells. Meiosis makes sex cells (gametes), sperm and egg, with half the chromosomes. Genesis 1:11 says, And God said, Let the earth bring forth grass, the herb yielding seed, and the fruit tree yielding fruit after his kind, whose seed is in itself, upon the earth: and it was so.\n\nChromosome numbers: Humans have 46 chromosomes in body cells (diploid, 2n), arranged as 23 homologous pairs: one chromosome from each parent. Gametes have 23 (haploid, n). When sperm and egg join in fertilization, the zygote has 46 again.\n\nMeiosis has two divisions:\nMeiosis I: homologous chromosomes pair up and separate. The cell number goes from 1 to 2, and each has 23 chromosomes (each still made of two chromatids).\nMeiosis II: sister chromatids separate, like mitosis. The result is 4 cells, each with 23 single chromosomes. All four are genetically different.\n\nSources of variation:\nCrossing over: in prophase I, homologous chromosomes swap pieces, making new combinations of alleles.\nIndependent assortment: the pairs line up in random ways, so humans can make 2 to the power 23, about 8 million, different gametes from one person.\nRandom fertilization: any sperm can join any egg.\nMutations add new alleles.\n\nNondisjunction occurs when chromosomes fail to separate, giving gametes with too many or too few chromosomes. Down syndrome is caused by an extra copy of chromosome 21.\n\nMitosis versus meiosis: Mitosis makes 2 identical diploid cells for growth and repair. Meiosis makes 4 different haploid cells for reproduction.\n\nYour task: (1) Compare mitosis and meiosis in a table. (2) Explain two ways meiosis produces variety. (3) A cell has 2n equal to 8. How many chromosomes are in each gamete?\n\nFlorida standards: SC.912.L.16.17.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.16.17", "script": "Welcome back. Dr. Jenkins here. Listen, Genesis one and eleven says, And God said, Let the earth bring forth grass, the herb yielding seed, and the fruit tree yielding fruit after his kind, whose seed is in itself, upon the earth: and it was so. Life reproduces after its kind, and meiosis is one of the ways He built it.\n\nMitosis makes identical body cells. Meiosis makes sex cells, sperm and egg, with half the chromosomes. Humans have forty six chromosomes in body cells, called diploid, arranged in twenty three homologous pairs, one chromosome of each pair from each parent. Gametes have twenty three, called haploid. When sperm and egg join in fertilization, the zygote has forty six again.\n\nNow watch this. Meiosis has two divisions. In meiosis one, the homologous chromosomes pair up and separate, giving two cells with twenty three chromosomes each. In meiosis two, the sister chromatids separate, like mitosis. The result is four cells, each with twenty three single chromosomes, and all four are genetically different.\n\nLook at where variation comes from. Crossing over, in prophase one, where homologous chromosomes swap pieces. Independent assortment, where the pairs line up in random ways, so one person can make two to the twenty third, about eight million, different gametes. Random fertilization, since any sperm can join any egg. And mutations add new alleles.\n\nSometimes chromosomes fail to separate. That is nondisjunction, and it gives gametes with too many or too few chromosomes. Down syndrome is caused by an extra copy of chromosome twenty one.\n\nTo compare, mitosis makes two identical diploid cells for growth and repair. Meiosis makes four different haploid cells for reproduction.\n\nYour task today. Compare mitosis and meiosis in a table. Explain two ways meiosis produces variety. And if a cell has two n equals eight, tell how many chromosomes are in each gamete. Take the four question check when you finish.\n\nEach person is a new and unique creation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Meiosis and Genetic Variation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Inheritance Patterns and Biotechnology$j$, $j${"readings": [{"title": "Jeremiah 1 (King James Version)", "url": "/portal/bible/Jeremiah/1"}], "body": "Gregor Mendel, an Augustinian monk who studied pea plants, discovered the basic rules of inheritance. A gene can have different forms called alleles. Dominant alleles (capital letter) show up when present. Recessive alleles (lowercase letter) show only when two copies are present.\n\nGenotype is the alleles an organism has (TT, Tt, tt). Phenotype is the trait that shows (tall or short). Homozygous means two matching alleles; heterozygous means two different alleles.\n\nPunnett squares predict offspring. Cross two heterozygous tall plants, Tt times Tt. The offspring are 1 TT, 2 Tt and 1 tt. That is 75 percent tall (dominant phenotype) and 25 percent short, a 3 to 1 ratio. The genotype ratio is 1 : 2 : 1.\n\nMendel's laws: Law of Segregation, the two alleles for a trait separate in gamete formation. Law of Independent Assortment, genes for different traits are sorted separately (when they are on different chromosomes).\n\nOther patterns: Incomplete dominance, a blend (red crossed with white makes pink). Codominance, both show (type AB blood has both A and B). Multiple alleles, as in blood types with alleles I A, I B and i. Sex linked traits, carried on the X chromosome, such as red green color blindness, appear more often in males, who have one X. Polygenic traits, such as height and skin color, depend on many genes.\n\nBiotechnology uses living things to make products or solve problems. Examples: gel electrophoresis separates DNA fragments by size for DNA fingerprinting; PCR copies small amounts of DNA; genetic engineering moves a gene, such as human insulin, into bacteria; GMO crops resist pests; cloning copies an organism; CRISPR edits genes.\n\nEffects: Benefits include medicines, crime solving, and better crops. Concerns include safety, privacy, cost and ethics. Proverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going. We weigh new technology with wisdom.\n\nYour task: (1) Cross Bb with Bb and give the genotype and phenotype ratios. (2) Tell how incomplete dominance differs from codominance. (3) Give one benefit and one concern of genetic engineering.\n\nFlorida standards: SC.912.L.16.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.16.1", "script": "Welcome back. Dr. Jenkins here. Listen, Gregor Mendel was a monk who studied pea plants, and he discovered the basic rules of inheritance. A gene can have different forms called alleles. A dominant allele, written with a capital letter, shows up when it is present. A recessive allele, with a lowercase letter, shows only when two copies are present. Genotype is the alleles you have, like big T big T, or big T little t. Phenotype is the trait that shows, like tall or short. Homozygous means two matching alleles. Heterozygous means two different alleles.\n\nNow watch this. A Punnett square predicts offspring. Cross two heterozygous tall plants, Tt times Tt. The offspring are one T T, two T t, and one t t. That is seventy five percent tall and twenty five percent short, a three to one ratio. The genotype ratio is one, two, one.\n\nMendel's laws. The law of segregation says the two alleles for a trait separate when gametes form. The law of independent assortment says genes for different traits are sorted separately when they are on different chromosomes.\n\nLook at other patterns. Incomplete dominance gives a blend, like red crossed with white making pink. Codominance shows both, like type A B blood. Blood types come from multiple alleles. Sex linked traits are carried on the X chromosome, like red green color blindness, and they show up more in males, who have only one X. Polygenic traits, like height, depend on many genes.\n\nNow biotechnology. Gel electrophoresis separates DNA fragments by size for DNA fingerprinting. PCR copies small amounts of DNA. Genetic engineering moves a gene, like human insulin, into bacteria. Cloning copies an organism. CRISPR edits genes. The benefits include medicines, solving crimes and better crops. The concerns include safety, privacy, cost and ethics. Proverbs fourteen and fifteen says, The simple believeth every word: but the prudent man looketh well to his going. We weigh new technology with wisdom.\n\nYour task today. Cross Bb with Bb and give the ratios. Tell how incomplete dominance differs from codominance. And give one benefit and one concern of genetic engineering. Take the four question check when you finish.\n\nKnowledge needs wisdom to guide it. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Inheritance Patterns and Biotechnology$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Genetics Problem Set and DNA Model$j$, $j${"prompt": "Part 1: DNA to Protein. Given the DNA template strand TAC CGA GGT TTC ATT, write the complementary mRNA, split it into codons, and use the code (AUG methionine, GCU alanine, CCA proline, AAG lysine, UAA stop) to name the amino acids until a stop codon. Explain each step in a sentence. Psalm 139:16 says, Thine eyes did see my substance, yet being unperfect; and in thy book all my members were written, which in continuance were fashioned, when as yet there was none of them.\n\nPart 2: Mutations. Change one base in your template and describe what happens to the mRNA and the protein. Tell whether your change is a substitution, insertion or deletion, and whether it is likely to be harmful.\n\nPart 3: Punnett Squares. Solve each with a full square and the genotype and phenotype ratios: (a) Tt times Tt. (b) Rr times rr. (c) A woman with blood type A (genotype I A i) and a man with type B (genotype I B i).\n\nPart 4: Mitosis and Meiosis. Make a comparison table with at least five rows, and explain how crossing over and independent assortment make siblings different.\n\nPart 5: Biotechnology and Wisdom. In one paragraph of at least 80 words, describe one use of biotechnology, give a benefit and a concern, and explain how Proverbs 14:15 helps us make wise decisions.", "rubric": "70 points. DNA to protein: 14 points. Mutations: 8 points. Punnett squares: 18 points. Mitosis and meiosis: 14 points. Biotechnology paragraph: 12 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Genetics Problem Set and DNA Model$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Written in His Book$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains in your own words how information in a gene becomes a protein, (2) describes why every person except identical twins has a unique set of DNA and gives one reason from meiosis, (3) tells how respecting the worth of every person should guide how we use genetic information and technology, and (4) connects your answer to Psalm 139:16, which says, Thine eyes did see my substance, yet being unperfect; and in thy book all my members were written, which in continuance were fashioned, when as yet there was none of them. Then write a respectful reply of at least 40 words to another student, or answer this question: Why might a single base change cause serious disease in one gene and no change in another? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Written in His Book$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: DNA Structure and Replication$j$, $j${"questions": [{"q": "In DNA, adenine pairs with:", "options": ["Uracil", "Cytosine", "Thymine", "Guanine"]}, {"q": "The complementary DNA strand for TACGGA is:", "options": ["ATGCCT", "ATGCCA", "TACGGA", "AUGCCU"]}, {"q": "A DNA sample has 20 percent cytosine. The percent of guanine is:", "options": ["60 percent", "20 percent", "30 percent", "40 percent"]}, {"q": "The enzyme that adds new nucleotides during replication is:", "options": ["Helicase", "DNA polymerase", "Amylase", "Catalase"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: DNA Structure and Replication$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,1,1}'::int[], array[$j$In DNA, A pairs with T and C pairs with G.$j$,$j$A pairs with T and C pairs with G, so TACGGA pairs with ATGCCT.$j$,$j$C and G are present in equal amounts.$j$,$j$DNA polymerase builds the new strand and proofreads it.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: DNA Structure and Replication$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: From Gene to Protein and Mutations$j$, $j${"questions": [{"q": "Transcribing the DNA sequence TAC GGA into mRNA gives:", "options": ["AUG GGA", "ATG CCT", "AUG CCU", "UAC GGA"]}, {"q": "The three base group on mRNA that codes for an amino acid is a:", "options": ["Gene", "Codon", "Anticodon", "Chromosome"]}, {"q": "Translation takes place at the:", "options": ["Vacuole", "Ribosome", "Cell wall", "Nucleus"]}, {"q": "A deletion of one base in a gene is usually serious because it:", "options": ["Has no effect", "Shifts the reading frame", "Adds a new chromosome", "Changes only one amino acid"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: From Gene to Protein and Mutations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,1}'::int[], array[$j$The mRNA is complementary and uses U in place of T.$j$,$j$Each codon specifies one amino acid or a stop signal.$j$,$j$Ribosomes read mRNA and build proteins.$j$,$j$A frameshift changes every codon after the deletion.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: From Gene to Protein and Mutations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Meiosis and Genetic Variation$j$, $j${"questions": [{"q": "Meiosis in a human cell produces:", "options": ["Two identical cells with 46 chromosomes", "Four genetically different cells with 23 chromosomes", "Four identical cells with 46 chromosomes", "One cell with 23 chromosomes"]}, {"q": "Crossing over occurs in:", "options": ["Prophase I of meiosis", "Cytokinesis of mitosis", "Interphase only", "Telophase of mitosis"]}, {"q": "A cell with 2n equal to 8 produces gametes with:", "options": ["16 chromosomes", "2 chromosomes", "8 chromosomes", "4 chromosomes"]}, {"q": "Down syndrome is caused by:", "options": ["A missing nucleus", "An infection", "A frameshift in one gene only", "An extra copy of chromosome 21"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Meiosis and Genetic Variation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,3,3}'::int[], array[$j$Meiosis makes four haploid cells that differ from each other.$j$,$j$Homologous chromosomes swap segments in prophase I.$j$,$j$Gametes are haploid, so they have half of 8.$j$,$j$Nondisjunction results in three copies of chromosome 21.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Meiosis and Genetic Variation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Inheritance Patterns and Biotechnology$j$, $j${"questions": [{"q": "A cross of Tt times Tt gives offspring that are about:", "options": ["25 percent dominant and 75 percent recessive", "100 percent dominant", "75 percent dominant phenotype and 25 percent recessive", "50 percent dominant and 50 percent recessive"]}, {"q": "An organism with the genotype Bb is:", "options": ["Homozygous recessive", "Haploid", "Homozygous dominant", "Heterozygous"]}, {"q": "A pink flower from crossing red and white is an example of:", "options": ["Codominance", "Cloning", "Incomplete dominance", "Mutation"]}, {"q": "Which technique separates DNA fragments by size?", "options": ["Photosynthesis", "Mitosis", "Gel electrophoresis", "Osmosis"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Inheritance Patterns and Biotechnology$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,2}'::int[], array[$j$The Punnett square gives 1 TT, 2 Tt and 1 tt.$j$,$j$It has two different alleles.$j$,$j$The offspring show a blend of the two parent traits.$j$,$j$DNA fragments move through a gel at different speeds based on size.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Inheritance Patterns and Biotechnology$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Heredity, DNA and Biotechnology$j$, $j${"questions": [{"q": "If one strand of DNA is AAGCT, the other strand is:", "options": ["UUCGA", "AAGCT", "CCTAG", "TTCGA"]}, {"q": "Which sequence correctly shows the flow of genetic information?", "options": ["Protein to RNA to DNA", "DNA to RNA to protein", "Protein to DNA to RNA", "RNA to protein to DNA"]}, {"q": "Which of these is found in RNA but not in DNA?", "options": ["Uracil", "Adenine", "Guanine", "Cytosine"]}, {"q": "A mutation that adds one base to a gene is a:", "options": ["Gamete", "Substitution only", "Frameshift", "Silent copy"]}, {"q": "Meiosis differs from mitosis because meiosis:", "options": ["Occurs in all body cells", "Makes two identical diploid cells", "Makes four haploid cells", "Has no crossing over"]}, {"q": "Two heterozygous parents (Aa times Aa) can have a child with the genotype:", "options": ["AaBb only", "AAa", "aa", "Ab"]}, {"q": "Which person is most likely to show a sex linked recessive trait carried on the X chromosome?", "options": ["Neither", "A male with one copy of the allele", "A female with one copy of the allele", "A cell without a nucleus"]}, {"q": "Human insulin made by bacteria is an example of:", "options": ["Natural selection", "Genetic engineering", "Meiosis", "Osmosis"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Heredity, DNA and Biotechnology$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,0,2,2,2,1,1}'::int[], array[$j$A pairs with T and G pairs with C.$j$,$j$Transcription makes RNA from DNA, and translation makes protein from RNA.$j$,$j$RNA uses uracil in place of thymine.$j$,$j$An insertion shifts the reading frame.$j$,$j$Meiosis makes four genetically different haploid cells.$j$,$j$A child can inherit a recessive allele from each parent.$j$,$j$Males have only one X, so one recessive allele shows.$j$,$j$A human gene was placed in bacteria so they make the protein.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Heredity, DNA and Biotechnology$j$ on conflict (item_id) do nothing;
